&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;-      &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;재택&amp;nbsp;근무편&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt; : &lt;/span&gt;&lt;a href=&quot;https://www.youtube.com/watch?v=X4haBKK02GY&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.youtube.com/watch?v=X4haBKK02GY&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
