&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;이커머스 &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;또는&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;온라인&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;플랫폼&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;관련&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;경험&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;이 있으신 분&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt; B2B &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;영업 &lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;또는&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고객&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;관리&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;경험&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;이 있으신 분&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
