&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul style=&quot;margin-top: 0in; margin-bottom: 0in;&quot; type=&quot;disc&quot;&gt;
&lt;li style=&quot;margin-top: 0; margin-bottom: 0; vertical-align: middle;&quot;&gt;&lt;span style=&quot;font-family: &#39;Malgun Gothic&#39;; font-size: 11.0pt;&quot;&gt;예산 수립 및 재무 계획&lt;/span&gt;&lt;span style=&quot;font-family: Calibri; font-size: 11.0pt;&quot;&gt;(Forecasting) &lt;/span&gt;&lt;span style=&quot;font-family: &#39;Malgun Gothic&#39;; font-size: 11.0pt;&quot;&gt;관리&lt;/span&gt;&lt;/li&gt;
