&lt;p&gt;&lt;strong&gt;자격&lt;/strong&gt; &lt;strong&gt;요건&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;학력&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;통번역&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;대학원&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;한영&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;통번역과&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;졸업&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;경력: 통번역 업무 경력을 보유하신 분&lt;/li&gt;
