&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;Basic Qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
